#include "config.h"

int main(void) {
    InicializarReloj();                 // F_CY = 40 MHz
    AD1PCFGL = 0xFFFF;                  // todos los pins en digital
    PORTB = 0xEFFF;
    TRISB = 0x0FFF;                     // LEDs como salidas
    TMR1 = 0;
    PR1 = 0xFFFF;                       // termina en 65535 cuentas
    IFS0bits.T1IF = 0;
    T1CON = 0x8030;                     // pre-escalado 256 y ON
    while (1) {
        PORTB ^= 0x1000;                // conmuta RB12
        while (IFS0bits.T1IF == 0)      // espera al final de cuenta
            ;
        IFS0bits.T1IF = 0;              // y borra el flag
    }
    return 0;
}
